import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"Utils API","link":"/api/Utils-API/Utils-API"},{"text":"SuperKernel","link":"/api/Utils-API/SuperKernel/SuperKernel"},{"text":"SK_BIND","link":"/api/Utils-API/SuperKernel/SK_BIND"}]},"headers":[],"relativePath":"api/Utils-API/SuperKernel/SK_BIND.md","filePath":"api/Utils-API/SuperKernel/SK_BIND.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件","link":"#需要包含的头文件"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788399502000}'),c={name:"api/Utils-API/SuperKernel/SK_BIND.md"};function t(e,s,i,d,r,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>SK_BIND<span id="ZH-CN_TOPIC_0000002565043461"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section259105813316"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>本接口为算子SuperKernel场景提供绑定原核函数（Kernel）和SK子函数的能力。核函数（Kernel）直调算子的完整适配方法请参见<a href="../../../guide/programming_guide/advanced_programming/super_kernel/kernel_direct_call_adaptation.html">核函数（Kernel）直调算子额外适配说明</a>。</p><h2 id="函数原型">函数原型<span id="section2067518173415"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#define SK_BIND(GF, cap, SK0,...)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section158061867342"></span><a class="header-anchor" href="#参数说明">​</a></h2><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>GF</td><td>输入</td><td>核函数（Kernel）签名。</td></tr><tr><td>cap</td><td>输入</td><td><code>uint64_t</code>类型，用于标记当前算子的SuperKernel特性。SuperKernel框架根据这些信息调整相应的同步和融合策略。各bit位可按位或组合：<br>• 1：early start wait flag，表示算子内使用了<a href="../../SIMD-API/basic_api/sync_control/inter_task_sync/WaitPreTaskEnd.html">WaitPreTaskEnd</a>接口。<br>• 2：early start set flag，表示算子内使用了<a href="../../SIMD-API/basic_api/sync_control/inter_task_sync/SetNextTaskStart.html">SetNextTaskStart</a>接口。<br>• 4：disable_dcci，表示当前算子需要SuperKernel框架关闭调用前后的DCCI ALL指令。详细说明请参见<a href="../../../guide/programming_guide/advanced_programming/super_kernel/operator_adaptation.html">算子适配说明</a>。<br>• 8：disable_batchmode_check，表示跳过当前算子的<code>__schedmode__</code>检查，使该算子可继续参与SuperKernel融合。<br>例如，同时配置early start wait flag和early start set flag时，cap取值为3。 <br>• 16：blockdim_scale_up, 表示算子已自行支持核数向上扩展。融合后，SuperKernel会按自身的核数启动该算子；算子需要自行保证在实际启动核数大于其原始核数时仍能正确执行。</td></tr><tr><td>SK0</td><td>输入</td><td>SK子函数签名。</td></tr><tr><td>...</td><td>输入</td><td>SK1~SK3。可选，可提供额外的SK子函数签名。SuperKernel可以为不同核指定不同的SK子函数缓解同地址访问开销。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section43265506459"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>一个核函数（Kernel）最多绑定四个SK子函数。</li><li>核函数（Kernel）直调算子目前仅支持在npugraph_ex后端进入SuperKernel，不支持GE图模式。</li></ul><h2 id="需要包含的头文件">需要包含的头文件<span id="section10354115115916"></span><a class="header-anchor" href="#需要包含的头文件">​</a></h2><p>使用该接口需要包含&quot;kernel_operator.h&quot;头文件。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;kernel_operator.h&quot;</span>
</code></pre></div><h2 id="调用示例">调用示例<span id="section990974612242"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例展示SK_BIND接口的基本用法，SK子函数签名、参数结构体定义等完整规则请参见<a href="../../../guide/programming_guide/advanced_programming/super_kernel/kernel_direct_call_adaptation.html">核函数（Kernel）直调算子额外适配说明</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;kernel_operator.h&quot;</span>

<span class="c1">// 原普通kernel保留（用于非SuperKernel场景）</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="p">)</span><span class="w"> </span>
<span class="p">{</span><span class="w"> </span>
<span class="w">    </span><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span><span class="w"> </span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">totalLength</span><span class="p">);</span><span class="w"> </span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Process</span><span class="p">();</span><span class="w"> </span>
<span class="p">}</span><span class="w"> </span>

<span class="c1">// 规则3：定义参数结构体（根据原global函数的实际参数定义）</span>
<span class="k">struct</span><span class="w"> </span><span class="nc">AddCustomArgs</span><span class="w"> </span><span class="p">{</span>
<span class="w">   </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">;</span><span class="w">                      </span><span class="c1">// 对应add_custom的第一个参数 </span>
<span class="w">   </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">;</span><span class="w">                      </span><span class="c1">// 对应add_custom的第二个参数 </span>
<span class="w">   </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">;</span><span class="w">                      </span><span class="c1">// 对应add_custom的第三个参数 </span>
<span class="w">   </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="p">;</span><span class="w">           </span><span class="c1">// 对应add_custom的第四个参数</span>
<span class="p">};</span><span class="w">  </span>
<span class="c1">// 定义一个带模板参数的SK子函数</span>
<span class="c1">// 模板参数仅用于实例化出不同的符号，不影响函数逻辑</span>
<span class="k">template</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">splitNum</span><span class="o">&gt;</span>
<span class="n">__sk__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">AddCustomArgs</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="cm">/* 可选添加sysArgs参数 */</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 从结构体中获取参数</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">y</span><span class="p">;</span><span class="w"> </span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">z</span><span class="p">;</span><span class="w"> </span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">args</span><span class="o">-&gt;</span><span class="n">totalLength</span><span class="p">;</span><span class="w"> </span>
<span class="w">    </span><span class="c1">// 规则5：逻辑与global函数一致</span>
<span class="w">    </span><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">totalLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Process</span><span class="p">();</span>
<span class="p">}</span>
<span class="c1">// 规则6：使用SK_BIND绑定</span>
<span class="c1">// 通过指定模板参数实例化出4个不同的符号</span>
<span class="c1">// cap取值4表示配置disable_dcci</span>
<span class="n">SK_BIND</span><span class="p">(</span><span class="n">add_custom</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">0</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">1</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">2</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="n">add_custom_sk</span><span class="o">&lt;</span><span class="mi">3</span><span class="o">&gt;</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const u=a(c,[["render",t]]);export{_ as __pageData,u as default};
